import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;

public class RestaurantDemo {
    public static void main(String[] args) {
        // A clock frozen at 09:30 - before the kitchen opens.
        Clock morning = Clock.fixed(Instant.parse("2024-05-01T09:30:00Z"), ZoneOffset.UTC);
        Restaurant tooEarly = new Restaurant(morning);
        System.out.println("At 09:30 -> " + tooEarly.placeOrder("Butter Chicken"));

        // A clock frozen at 12:15 - orders are open.
        Clock lunch = Clock.fixed(Instant.parse("2024-05-01T12:15:00Z"), ZoneOffset.UTC);
        Restaurant open = new Restaurant(lunch);
        System.out.println("At 12:15 -> " + open.placeOrder("Butter Chicken"));

        // Exactly 11:00 counts as open, because isBefore is not inclusive.
        Clock opening = Clock.fixed(Instant.parse("2024-05-01T11:00:00Z"), ZoneOffset.UTC);
        System.out.println("At 11:00 -> " + new Restaurant(opening).placeOrder("Samosa"));
    }
}
